import React, { useState } from 'react';
import { Bot } from 'lucide-react';
import { usePluginState } from '../hooks/usePluginState';
import { MoaAssistant } from './MoaAssistant';
import { useMoaRun, useQuickActions } from './terminalShared';

/**
 * aiMONK – globaler KI-Assistent
 * ==============================
 * Freitext-Aufgaben werden über den MoaAgent (DeepSeek V4 Flash via
 * Server-Proxy) geplant und plugin-bewusst ausgeführt. Zusätzlich direkte
 * Transport-/Kompositions-Kurzbefehle für den laufenden Betrieb.
 */
export const AiMonkTerminal = React.memo(function AiMonkTerminal() {
  const { state, updateState } = usePluginState('ai', 'PRO');
  const [task, setTask] = useState('');
  const { run, results, busy, live } = useMoaRun({
    pluginId: 'ai',
    maxResults: 20,
    onSettled: () => setTask(''),
  });
  const quickActions = useQuickActions(run);

  return (
    <div className="w-full h-full flex flex-col bg-[#111] rounded-xl border border-neutral-800 overflow-hidden text-neutral-300 font-sans">
      <div className="px-6 py-2 border-b border-neutral-800 bg-black/20">
        <MoaAssistant pluginId="ai" placeholder="MOA: globale Aufgabe…" onActivity={(active) => updateState(active ? 'AUTO_AI' : state)} autoMode={state === 'AUTO_AI'} />
      </div>
      <div className="flex items-center justify-between px-6 py-4 bg-linear-to-r from-cyan-900/20 to-[#111] border-b border-cyan-900/30">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center border border-cyan-500/50">
            <Bot className="w-5 h-5 text-cyan-400" />
          </div>
          <h2 className="text-xl font-black tracking-widest text-neutral-100 uppercase">aiMONK</h2>
        </div>
        <select value={state} onChange={(e) => updateState(e.target.value as never)} className="bg-black text-white text-xs p-1 rounded">
          <option value="OFF">OFF</option>
          <option value="AUTO_AI">AI</option>
          <option value="PRO">ACTIVE</option>
        </select>
      </div>

      <div className="flex-1 p-6 overflow-y-auto space-y-6">
        <div className="flex gap-2">
          <input
            value={task}
            onChange={(e) => setTask(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') void run(task); }}
            placeholder="Aufgabe eingeben, z. B. 'Mastering-Kette prüfen' oder 'Drop vorbereiten'"
            className="flex-1 bg-[#1a1a1a] border border-neutral-800 rounded-lg px-4 py-3 text-sm text-white placeholder-neutral-600 focus:outline-none focus:border-cyan-500/60"
          />
          <button type="button" onClick={() => void run(task)} disabled={busy || !task.trim()} className="px-5 py-3 rounded-lg border border-cyan-500/60 bg-cyan-500/10 text-cyan-200 text-xs font-black tracking-widest hover:bg-cyan-500/20 disabled:opacity-40">
            {busy ? 'PLANT…' : 'AUSFÜHREN'}
          </button>
        </div>

        <div className="flex flex-wrap gap-2">
          {quickActions.map((action) => (
            <button key={action.label} type="button" onClick={action.run} className="flex items-center gap-2 px-4 py-2 rounded-full border border-neutral-700 bg-black/40 text-[10px] font-black tracking-widest text-neutral-300 hover:border-cyan-400/60 hover:text-cyan-200 transition-colors">
              <action.icon className="w-3 h-3" /> {action.label}
            </button>
          ))}
        </div>

        <div className="bg-black/40 border border-neutral-800 rounded-xl p-4 min-h-[160px]">
          <h3 className="text-[10px] font-bold tracking-[0.3em] text-neutral-500 uppercase mb-2">Ausführungs-Log</h3>
          <div className="space-y-1 font-mono text-[11px]">
            {busy && live && (
              <div className="text-cyan-300 whitespace-pre-wrap break-words" aria-live="polite" data-testid="aimonk-live">{live}</div>
            )}
            {results.length === 0 && !live && <div className="text-neutral-600">Noch keine Ausführung – Aufgabe eingeben oder Kurzbefehl wählen.</div>}
            {results.map((line, i) => (
              <div key={i} className={line.startsWith('✓') ? 'text-emerald-400' : 'text-red-400'}>{line}</div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
});

import { useState, useEffect, useRef } from 'react';
import { moaAgent, type MoaStep } from '../core/ai/MoaAgent';
import { moaHistory } from '../core/ai/MoaHistory';
import { storageGetJson, storageSetJson } from '../utils/storage';
import { moaTaskForPlugin } from '../utils/prompts';

interface MoaAssistantProps {
  pluginId: string;
  placeholder?: string;
  /** Wird bei MOA-Start/-Ende aufgerufen, damit das Terminal AUTO_AI anzeigen kann. */
  onActivity?: (active: boolean) => void;
  /** AUTO_AI-Modus: periodische, plugin-spezifische MOA-Vorschläge ausführen. */
  autoMode?: boolean;
}

const AUTO_FIRST_MS = 2500;
const AUTO_INTERVAL_MS = 90000;

/**
 * audioMONASTRY · MoaAssistant (AUTO_AI je Plugin, ohne eigene Zeile)
 * ====================================================================
 * Design: Eingabe, Agent-Läufe und Fehler stehen nur im aiMONK-Dock. Hier
 * bleibt der AUTO_AI-Takt: MoaAgent plant → plugin-bewusste Ausführung.
 * Im AUTO_AI-Modus werden periodisch Vorschläge geplant und ausgeführt;
 * alle Läufe landen in der zentralen MoaHistory.
 */
export function MoaAssistant({ pluginId, onActivity, autoMode = false }: MoaAssistantProps) {
  const [busy, setBusy] = useState(false);
  const [log, setLog] = useState<string[]>(() => storageGetJson<string[]>(`moa-log-${pluginId}`) ?? []);
  const busyRef = useRef(false);

  useEffect(() => {
    busyRef.current = busy;
  }, [busy]);

  // Letzte MOA-Ergebnisse pro Plugin persistieren (max. 5 Einträge).
  useEffect(() => {
    if (log.length > 0) storageSetJson(`moa-log-${pluginId}`, log.slice(-5));
  }, [log, pluginId]);

  const runTask = async (input: string, auto = false) => {
    if (busyRef.current) return;
    busyRef.current = true;
    setBusy(true);
    onActivity?.(true);
    try {
      const plan = await moaAgent.plan(`${pluginId}: ${input}`);
      const steps: MoaStep[] = plan.steps.length
        ? plan.steps
        : [{ pluginId, command: input, prompt: input }];
      const results = await moaAgent.executePlan({ ...plan, steps }, 'localUser');
      const entries = results.map((r) =>
        `${r.handled ? '✓' : '✗'} ${r.pluginId || r.step.pluginId}: ${r.step.command}${r.error ? ` (${r.error})` : ''}`,
      );
      setLog((prev) => [...prev.slice(-4), ...(auto ? entries.map((e) => `AUTO: ${e}`) : entries)]);
      moaHistory.add({
        pluginId,
        task: input,
        provider: plan.provider,
        results: entries,
        at: Date.now(),
      });
    } catch (error) {
      const msg = `Fehler: ${error instanceof Error ? error.message : String(error)}`;
      setLog((prev) => [...prev.slice(-4), msg]);
      moaHistory.add({ pluginId, task: input, provider: 'error', results: [msg], at: Date.now() });
    } finally {
      busyRef.current = false;
      setBusy(false);
      onActivity?.(false);
    }
  };

  // AUTO_AI: periodische, plugin-spezifische Vorschläge planen und ausführen.
  useEffect(() => {
    if (!autoMode) return;
    const tick = () => {
      runTask(moaTaskForPlugin(pluginId), true).catch(() => { /* Fehler werden in runTask geloggt */ });
    };
    const first = window.setTimeout(tick, AUTO_FIRST_MS);
    const interval = window.setInterval(tick, AUTO_INTERVAL_MS);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(interval);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoMode, pluginId]);

  // Design (Entwurf): keine KI-Zeilen in den Plugins – Aufgaben, Agent-Läufe
  // und Fehler stehen nur im aiMONK-Dock. Hier läuft nur noch AUTO_AI.
  return null;
}

